package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.core.*;import net.minecraft.server.level.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.damagesource.*;import net.minecraft.world.level.*;import net.minecraft.world.phys.*;import java.util.*;import java.lang.reflect.*;
/** PB-specific material adapter to the existing PS-01 explosion/impact pipeline, not a second explosion engine. */
public final class Pb01Protection{
 public record Cover(BlockPos root,UUID id,Direction face,int mask,int step,double[]health){}private record Target(Cover cover,int zone,Vec3 point,double distance){}
 private static final class Blast{ServerLevel level;Explosion event;Vec3 origin;float radius;long time;List<Cover>covers=new ArrayList<>();Map<BlockPos,Set<Target>>proposed=new HashMap<>();Set<Target>accepted=new HashSet<>();Blast(ServerLevel l,Explosion e){level=l;event=e;origin=e.getPosition();radius=((nl.smartstreamlabs.sbwdroneconfig.mixin.RubbleExplosionAccess)e).rubble$radius();time=l.getGameTime();}}
 private static final Map<DamageSource,Blast>SOURCES=new WeakHashMap<>();private static final Map<Explosion,Blast>EVENTS=new WeakHashMap<>();private static final ArrayDeque<Blast>PENDING=new ArrayDeque<>();private static final Map<Class<?>,Method[]>METHODS=new HashMap<>();
 public static List<Pb01BlockEntity>near(ServerLevel l,AABB bounds){var out=new ArrayList<Pb01BlockEntity>();for(var e:Pb01WorldData.get(l).near(((int)Math.floor(bounds.minX))>>4,((int)Math.floor(bounds.minZ))>>4,((int)Math.floor(bounds.maxX))>>4,((int)Math.floor(bounds.maxZ))>>4))if(l.hasChunkAt(e.root)&&l.getBlockEntity(e.root)instanceof Pb01BlockEntity b&&!b.removing&&b.id.equals(e.id)&&b.getRenderBoundingBox().intersects(bounds))out.add(b);return out;}
 private static Cover snapshot(Pb01BlockEntity b){return new Cover(b.getBlockPos(),b.id,b.facing(),b.mask(),b.doorStep(),b.integrity());}
 private static Vec3 nearest(AABB b,Vec3 p){return new Vec3(Math.max(b.minX,Math.min(b.maxX,p.x)),Math.max(b.minY,Math.min(b.maxY,p.y)),Math.max(b.minZ,Math.min(b.maxZ,p.z)));}
 private static Vec3 exposed(ServerLevel l,Cover c,int zone,Vec3 source,double reach){var g=Pb01Geometry.MODEL;var choices=new ArrayList<AABB>();for(var a:g.material(zone,c.step))choices.add(Pb01Geometry.box(c.root,c.face,a));choices.sort(Comparator.comparingDouble(a->a.distanceToSqr(source)));for(int i=0;i<Math.min(3,choices.size());i++){var at=nearest(choices.get(i),source);if(at.distanceToSqr(source)>reach*reach)continue;var delta=at.subtract(source);var end=at.add(delta.normalize().scale(.1));if(!Hgd01Lasers.loaded(l,source,end))continue;var hit=l.clip(new ClipContext(source,end,ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,(Entity)null));if(hit.getType()==HitResult.Type.MISS)return at;if(l.getBlockState(hit.getBlockPos()).getBlock()instanceof Pb01Block&&Pb01Block.root(hit.getBlockPos(),l.getBlockState(hit.getBlockPos())).equals(c.root)&&g.hitZone(Pb01Geometry.local(c.root,c.face,hit.getLocation()),c.mask,c.step)==zone)return hit.getLocation();}return null;}
 public static void prepare(ServerLevel l,Explosion e,List<BlockPos>blocks){var context=new Blast(l,e);double reach=Math.min(64,Math.max(1,context.radius*2));var existing=new HashSet<>(blocks);int remaining=Pb01Config.MAX_BLAST_ZONES.get();boolean wear=Pb01Config.terrain()&&((nl.smartstreamlabs.sbwdroneconfig.mixin.Pb01ExplosionAccess)e).pb01$blocks()!=Explosion.BlockInteraction.KEEP&&(!(e instanceof com.atsuishio.superbwarfare.tools.CustomExplosion)||!RubbleConfig.RESPECT_SBW.get()||com.atsuishio.superbwarfare.config.server.ExplosionConfig.EXPLOSION_DESTROY.get())&&(l.getGameRules().getBoolean(GameRules.RULE_MOBGRIEFING)||!(e.getDirectSourceEntity()instanceof net.minecraft.world.entity.Mob||e.getIndirectSourceEntity()instanceof net.minecraft.world.entity.Mob));
  for(var b:near(l,new AABB(context.origin,context.origin).inflate(reach))){if(context.covers.size()>=32)break;var c=snapshot(b);context.covers.add(c);if(!wear)continue;for(int zone=0;zone<16&&remaining>0;zone++){if((c.mask&(1<<zone))==0)continue;var at=exposed(l,c,zone,context.origin,reach);if(at==null)continue;remaining--;var t=new Target(c,zone,at,at.distanceTo(context.origin));var g=Pb01Geometry.MODEL;for(boolean moving:new boolean[]{false,true}){var cells=moving?g.door:g.body;var bases=moving?g.doorBase:g.bodyBase;for(int i=0;i<cells.length;i++)if((g.variant(moving,bases[i]).mask()&(1<<zone))!=0){var p=Pb01Geometry.cell(c.root,c.face,cells[i]);if(!l.hasChunkAt(p)||!(l.getBlockState(p).getBlock()instanceof Pb01Block))continue;context.proposed.computeIfAbsent(p,k->new HashSet<>()).add(t);if(existing.add(p))blocks.add(p);}}}}
  SOURCES.entrySet().removeIf(v->v.getValue().time<l.getGameTime()-2||v.getValue().level!=l);SOURCES.put(((nl.smartstreamlabs.sbwdroneconfig.mixin.Vc01ExplosionAccess)e).vc01$source(),context);EVENTS.put(e,context);
 }
 public static void finish(Explosion e,List<BlockPos>blocks){var c=EVENTS.remove(e);if(c==null)return;var retained=new HashSet<>(blocks);var denied=new HashSet<Target>();for(var entry:c.proposed.entrySet()){if(retained.contains(entry.getKey()))c.accepted.addAll(entry.getValue());else denied.addAll(entry.getValue());}c.accepted.removeAll(denied);blocks.removeIf(p->c.level.getBlockState(p).getBlock()instanceof Pb01Block);if(PENDING.size()<128)PENDING.add(c);}
 public static void tick(){while(!PENDING.isEmpty()){var c=PENDING.removeFirst();for(var v:c.event.getHitPlayers().entrySet())if(v.getKey()instanceof ServerPlayer p){double reduction=reduction(p,c.origin,c.covers,true);if(reduction>0&&v.getValue().lengthSqr()>0){p.setDeltaMovement(p.getDeltaMovement().subtract(v.getValue().scale(reduction)));p.hurtMarked=true;p.connection.send(new net.minecraft.network.protocol.game.ClientboundSetEntityMotionPacket(p));}}for(var t:c.accepted){var at=t.cover.root;if(!c.level.hasChunkAt(at)||!(c.level.getBlockEntity(at)instanceof Pb01BlockEntity b)||!b.id.equals(t.cover.id))continue;double amount=Pb01Config.BLAST_WEAR.get()*c.radius*Math.max(0,1-t.distance/Math.max(1,c.radius*2));b.hit(t.zone,Math.min(Pb01Config.health(t.zone)*.20,amount),t.point);}}}
 private static double reduction(LivingEntity p,Vec3 origin,List<Cover>covers,boolean blast){double out=0;var box=p.getBoundingBox();double h=box.getYsize(),w=box.getXsize();var points=new Vec3[]{p.position().add(0,h*.5,0),p.position().add(0,h*.9,0),p.position().add(0,h*.14,0),p.position().add(w*.38,h*.55,0),p.position().add(-w*.38,h*.55,0)};for(var c:covers){double least=1;var start=Pb01Geometry.local(c.root,c.face,origin);for(var at:points)least=Math.min(least,Pb01Geometry.MODEL.cover(start,Pb01Geometry.local(c.root,c.face,at),c.mask,c.step,c.health,blast));out=Math.max(out,least);}return Math.min(.99,out);}
 public static float reduce(LivingEntity p,DamageSource s,float amount){if(!(p instanceof Player)||!(p.level()instanceof ServerLevel l)||!(amount>0)||!Ps01Protection.explosion(s)&&!Ps01Protection.projectile(s))return amount;var c=SOURCES.get(s);boolean known=c!=null&&c.level==l&&c.time>=l.getGameTime()-2;Vec3 at=known?c.origin:s.getSourcePosition();if(!Ps01Protection.explosion(s)&&s.getDirectEntity()!=null){var n=s.getDirectEntity().getPersistentData();if(n.contains("PsCoverTime")&&n.getLong("PsCoverTime")>=l.getGameTime()-2)at=new Vec3(n.getDouble("PsCoverX"),n.getDouble("PsCoverY"),n.getDouble("PsCoverZ"));}if(at==null)return amount;var covers=known?c.covers:near(l,p.getBoundingBox().inflate(12)).stream().map(Pb01Protection::snapshot).toList();return(float)(amount*(1-reduction(p,at,covers,Ps01Protection.explosion(s))));}
 private static Method method(Class<?>c,String...names){for(var n:names)try{return c.getMethod(n);}catch(NoSuchMethodException ignored){}return null;}private static double value(Entity e,Method m,double fallback){if(m==null)return fallback;try{var v=m.invoke(e);return v instanceof Number n?n.doubleValue():fallback;}catch(ReflectiveOperationException ex){return fallback;}}
 public static void impact(Entity projectile,BlockHitResult hit){if(!(projectile.level()instanceof ServerLevel l)||!Pb01Config.terrain()||Pb01Config.IMPACT_WEAR.get()<=0)return;var s=l.getBlockState(hit.getBlockPos());if(!(s.getBlock()instanceof Pb01Block))return;var b=Pb01Block.main(l,hit.getBlockPos(),s);if(b==null)return;var methods=METHODS.computeIfAbsent(projectile.getClass(),k->new Method[]{method(k,"getDamage","getDamageValue","getBaseDamage"),method(k,"getExplosionRadius","getExplosionRadiusValue")});if(value(projectile,methods[1],0)>0)return;int zone=Pb01Geometry.MODEL.hitZone(Pb01Geometry.local(b.getBlockPos(),b.facing(),hit.getLocation()),b.mask(),b.doorStep());if(zone<0)return;var data=projectile.getPersistentData();String key="PbHit"+zone;long tick=l.getGameTime();if(data.contains(key)&&data.getLong(key)==tick&&data.getLong(key+"Root")==b.getBlockPos().asLong())return;Entity owner=projectile instanceof net.minecraft.world.entity.projectile.Projectile p?p.getOwner():null;ServerPlayer actor=owner instanceof ServerPlayer p?p:net.minecraftforge.common.util.FakePlayerFactory.get(l,new com.mojang.authlib.GameProfile(owner==null?UUID.fromString("c591cd8b-ad45-44e5-9990-3472eaf1a13e"):owner.getUUID(),"[Drone Warfare]"));if(!Pb01Events.permitBreak(actor,hit.getBlockPos()))return;data.putLong(key,tick);data.putLong(key+"Root",b.getBlockPos().asLong());var from=hit.getLocation().subtract(projectile.getDeltaMovement().normalize().scale(.12));data.putLong("PsCoverTime",tick);data.putDouble("PsCoverX",from.x);data.putDouble("PsCoverY",from.y);data.putDouble("PsCoverZ",from.z);b.hit(zone,Math.min(100,Math.max(.5,(projectile instanceof net.minecraft.world.entity.projectile.AbstractArrow arrow?arrow.getBaseDamage():value(projectile,methods[0],4))*Pb01Config.IMPACT_WEAR.get())),hit.getLocation());}
 public static void reset(){SOURCES.clear();EVENTS.clear();PENDING.clear();}
}
